import {choiceModel} from './option-choice-model.mjs';
import {applySchoolPolicy,teacherLimit,defaultYearBands,teachingBand} from './timetable-policy.mjs';
import {teacherSubjects} from './timetable-manager-inputs.mjs';
const slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-');
export function buildOptionPlan(base,data,{continuation=false}={}){
 const records=Object.values(data.records),ids=new Set(records.map(r=>r.studentId));if(!ids.size)throw Error('Submit some Year 10 choices before creating the planning draft.');
 const p=structuredClone(base),year=continuation?11:10;p.rooms=p.rooms.filter(r=>!r.groupId||Number(base.groups.find(g=>g.id===r.groupId)?.year)>=7);p.groups=p.groups.filter(g=>g.year===10).map(g=>({...g,id:continuation?'continuation-'+g.id:g.id,year,name:continuation?g.name.replace(/10/g,'11')+' · continuation':g.name,studentIds:g.studentIds.filter(id=>ids.has(id))})).filter(g=>g.studentIds.length);const groupsFor=students=>p.groups.filter(g=>g.studentIds.some(id=>students.includes(id))).map(g=>g.id);
 p.teachers=p.teachers.map(t=>({...t,subjectIds:teacherSubjects(base,t.id),committedLoad:continuation?0:base.activities.filter(a=>a.year!==10&&a.teacherIds.includes(t.id)).reduce((n,a)=>n+a.weeklyCount*a.duration,0),committedBands:continuation?{}:Object.fromEntries(['primary','lower','igcse','as','a2'].map(b=>[b,base.activities.filter(a=>a.year!==10&&a.teacherIds.includes(t.id)&&teachingBand(a.year)===b).reduce((n,a)=>n+a.weeklyCount*a.duration,0)])),duty:t.duty||'Teacher',yearBands:t.yearBands||defaultYearBands(t,base)}));p.activities=p.activities.filter(a=>a.year===10&&['assembly','pe','pshe'].includes(a.subjectId)).map(a=>({...a,year,studentIds:a.studentIds.filter(id=>ids.has(id)),groupIds:groupsFor(a.studentIds.filter(id=>ids.has(id))),name:continuation?a.name.replace(/10/g,'11')+' · continuation':a.name})).filter(a=>a.studentIds.length);p.optionBlocks=[];p.optionEligibility={};p.placements={};p.optionModels={10:'3',11:'3'};p.demonstrationModel='3';p.optionSource='Timetable options 2025_26.docx';p.planningYear=continuation?'2027–28':'2026–27';p.scope='year10-choices';p.name='WIST · '+p.planningYear+' · Year '+year+' Model 3 choices';p.optionCollection={model:'3',revision:data.revision,submitted:ids.size,total:data.cohortSize,continuation,sourceYear:10};p.managerWorkflow={reviews:{}};
 for(const r of records)p.optionEligibility[r.studentId]={nonUzbek:!!r.nonUzbek,declared:true};
 choiceModel.blocks.forEach((choices,i)=>{const blockId='option-'+year+'-'+'ABCDEFGHI'[i],block={id:blockId,name:'Year '+year+' · Option '+(i+1),year,modelId:'3',activityIds:[],studentIds:[...ids],weeklyCount:4,duration:1,documentChoices:structuredClone(choices)};for(const c of choices){const roster=records.filter(r=>r.choices[i]===c.subject).map(r=>r.studentId);for(let n=0;n<roster.length;n+=24){const studentIds=roster.slice(n,n+24),subjectId=slug(c.subject),id='chosen-'+year+'-'+'ABCDEFGHI'[i]+'-'+subjectId+'-'+(n/24+1),source=base.activities.find(a=>a.subjectId===subjectId),types=new Set(p.rooms.filter(r=>source?.roomIds?.includes(r.id)).map(r=>r.type)),rooms=p.rooms.filter(r=>(types.size?types.has(r.type):r.type==='general')&&r.capacity>=studentIds.length).map(r=>r.id);if(!p.subjects.some(s=>s.id===subjectId))p.subjects.push({id:subjectId,name:c.subject,color:'#486e7d'});p.activities.push({id,name:'Year '+year+' · Option '+(i+1)+' · '+c.subject+' · Class '+(n/24+1),year,subjectId,studentIds,groupIds:groupsFor(studentIds),teacherIds:source?.teacherIds?.length?[source.teacherIds[0]]:[base.teachers[0].id],roomIds:rooms,weeklyCount:4,duration:1,spread:false,blockId,science:c.science,nonUzbekOnly:c.nonUzbekOnly});block.activityIds.push(id);}}p.optionBlocks.push(block);});
 for(const subjectId of ['assembly','pshe','pe']){const activities=p.activities.filter(a=>a.subjectId===subjectId),id='choice-core-'+year+'-'+subjectId;for(const a of activities)a.blockId=id;if(activities.length)p.optionBlocks.push({id,name:'Year '+year+' · '+subjectId,year,subjectId,activityIds:activities.map(a=>a.id),studentIds:[...ids],weeklyCount:activities[0].weeklyCount,duration:activities[0].duration});}
 p.notes=['Model 3 submitted choices. '+ids.size+' / '+data.cohortSize+' students submitted.','Class cap 24. A–E have one option class per subject; language/core subjects split into parallel sections.','Year 11 continuation preserves the same student IDs and selected subjects; lesson times may be regenerated.'];
 const result=applySchoolPolicy(p);result.optionCollection=p.optionCollection;result.continuationChoices=Object.fromEntries(records.map(r=>[r.studentId,[...r.choices]]));return result;
}
export function staffingSummary(p){return p.teachers.map(t=>{const rows=p.activities.filter(a=>a.teacherIds.includes(t.id));return{name:t.name,duty:t.duty||'Teacher',limit:teacherLimit(t),load:(t.committedLoad||0)+rows.reduce((n,a)=>n+a.weeklyCount*a.duration,0),inDraft:rows.reduce((n,a)=>n+a.weeklyCount*a.duration,0),committed:t.committedLoad||0,years:[...new Set(rows.map(a=>a.year))].sort((a,b)=>a-b)};}).filter(t=>t.load);}
